mapper.select:


    inner join sys_user u on u.user_name = drepairreport.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'

left join d_equipment e ON drepairreport.equipment_id = e.id

    drepairreport.del_flag = '0'
     and drepairreport.equipment_id = #{equipmentId}
     and drepairreport.faulty_accessory_name like concat('%', #{faultyAccessoryName}, '%')
     and drepairreport.fault_message = #{faultMessage}
     and drepairreport.fault_lv = #{faultLv}
     and drepairreport.equipment_status = #{equipmentStatus}
     and drepairreport.is_shutdown = #{isShutdown}
     and drepairreport.img = #{img}
     and drepairreport.company_id = #{companyId}
     and drepairreport.executor_id = #{executorId}
     and e.name = #{equName}
     and drepairreport.create_by = #{createBy}



${params.dataScope}
